INSERT INTO routes (id, kind, name, region, status, difficulty, distance_km, gain_m, loss_m, date_start, date_end, from_point, to_point, season, forecast_link, bus_link, bdz_link, avtogari_link, route_line, verification_level, transport, huts, risk, days, accommodation, taxis, windy_embed, notes_default) VALUES ('R05', 'detailed', 'Водопаден', 'Рила', 'Планиран', 'Средна/Висока', 16, 1000, 1000, '', '', '', '', 'Юни – Октомври', 'https://www.google.com/search?q=windy+prognoza+Belmeken', 'https://avtogari.info/', 'https://razpisanie.bdz.bg/', 'https://avtogari.info/', 'Костенец (жп/автобус) → х. Белмекен → яз. Белмекен → Сестримо', 'ДОБРО — х. Белмекен контакти в базата съвпадат с публични източници.', '{"summary":"ЖП/автобус до Костенец, после планински път до х. Белмекен; връзки към Сестримо/Язовир с местни пътища.","car":{"available":true,"text":"Асфалт до Костенец и до Белмекен (пътища до хижата са проходими за леки коли в сухо време).","parkingNote":"Паркинг при х. Белмекен; при дъжд последните участъци могат да са по-трудни за ниски автомобили."},"public":{"steps":[{"from":"София","to":"Костенец","mode":"Влак","time":"~1-1.5ч","note":"От Костенец се включва местен транспорт/такси към х. Белмекен."},{"from":"Сестримо","to":"София","mode":"Автобус/влак (през Костенец)","time":"~1.5ч","note":"Проверете разписанията за обратно връщане."}]}}'::jsonb, '[{"name":"х. Белмекен","elevation":2208,"beds":39,"officialPhone":"0879 461899","altPhone":"0889 798 586","email":null,"gps":"42.1930,23.7495","verified":true,"conflict":"Телефоните съвпадат с публикувани източници; проверете преди резервация."}]'::jsonb, '{"level":"СРЕДЕН","color":"amber","points":["Терен: денивелации и каменисти участъци; специфични участъци около язовира могат да бъдат хлъзгави.","Инциденти: няма широко документирани технически инциденти, но има случаи на умора/обезводняване.","Сезонност: зимата може да наложи специална екипировка за сняг и лед."],"conclusion":"Подходящ за опитни туристи и добре подготвени групи; подходящ уикенд маршрут без кола при добра организация."}'::jsonb, '[{"date":null,"label":"Костенец → х. Белмекен","type":"Преход","distance":"8-9 км","gain":"~1000м","time":"4-6ч","stay":"х. Белмекен","difficulty":"Среден/Висок"},{"date":null,"label":"х. Белмекен → яз. Белмекен → Сестримо","type":"Преход/слизане","distance":"7-8 км","gain":"~0-200м","time":"3-5ч","stay":"Сестримо/Костенец","difficulty":"Среден"}]'::jsonb, '[{"name":"х. Белмекен (в хижа)","location":"Белмекен","rating":null,"price":null,"note":"Хижа с капацитет, контакти предоставени; резервирайте предварително."},{"name":"Хотели в Костенец/Сестримо","location":"Костенец/Сестримо","rating":null,"price":null,"note":"Опции за нощувка преди/след маршрута."}]'::jsonb, '[{"name":"Такси Костенец","phone":"0301 6147 (примерен регионален номер)","note":"Регионални таксита обслужват Костенец и околността; конкретни номера да се валидират."}]'::jsonb, 'https://embed.windy.com/embed.html?type=map&location=coordinates&metricRain=mm&metricWind=km%2Fh&zoom=10&overlay=rain&product=ecmwf&level=surface&lat=42.1930&lon=23.7495', ''),
('breznik-sv-nikola', 'detailed', 'Брезник – Св. Никола', 'Вискяр планина', 'Идея', 'Лесна', 0.5, 70, 70, '', '', '', '', 'Юни – Ноември; зимата е възможна, но с повишено внимание', 'https://www.google.com/search?q=prognoza+Breznik+Viskyar', '', '', '', 'Брезник → връх Свети Никола → връщане по същия път; алтернативно Брезник → Брусник → връх Свети Никола.', 'ДОБРО — потвърден с маршрутно описание и отделен източник за краткия вариант от Брусник до върха.', '{"summary":"Най-логично е с кола до Брезник или Брусник; обществен транспорт и таксита не са потвърдени от надеждни източници.","car":{"available":true,"text":"До началото в Брезник се стига по път; при варианта през Брусник има място за оставяне на автомобил близо до разклона.","parkingNote":"Паркиране в центъра на Брезник или на уширение при Брусник; GPS за паркинг не е потвърден."},"public":{"steps":[]}}'::jsonb, '[{"name":"х. Брезите","elevation":null,"beds":null,"officialPhone":"0889 316 172","altPhone":"0887 255 951","email":null,"gps":null,"verified":true,"conflict":"Потвърден е контактният телефон от един източник; втори независим източник не е намерен тук."}]'::jsonb, '{"level":"НИСЪК","color":"emerald","points":["Маршрутът е кратък и ориентировъчно лесен.","През зимата е възможно залъгване в източната част и при пътищата около Брезник.","Основният риск е ориентирането по второстепенните пътища, не технически терен."],"conclusion":"Кратък и нискорисков маршрут с лека сложност; зимата изисква повече внимание."}'::jsonb, '[{"date":null,"label":"Брезник → връх Свети Никола","type":"Преход","distance":"0.5 км","gain":"70 м","time":"15 мин","stay":"х. Брезите","difficulty":"Лесна"}]'::jsonb, '[{"name":"Хотел-ресторант \"Хижата\"","location":"Брезник","rating":null,"price":null,"note":"Посочени са 16 легла и контактни телефони."},{"name":"ХИЖА “БРЕЗИТЕ”","location":"лесопарк Бърдото, Брезник","rating":null,"price":null,"note":"Посочена е като туристически обект близо до маршрута."}]'::jsonb, '[]'::jsonb, '', ''),
('zeleni-preslap-kabul', 'detailed', 'Зелени Преслап – Кабул', 'Рила', 'Идея', 'Висока', 5.5, 900, 900, '', '', '', '', 'Юни – Октомври; при стабилно време и без снеговалеж', 'https://www.google.com/search?q=prognoza+Zeleni+Preslap+Rila', '', '', '', 'Зелени Преслап → овчарници с вода → връх Кабул; алтернативи: връщане към Зелени Преслап, слизане към х. Скакавица или продължение към Седемте рилски езера / х. Иван Вазов.', 'ДОБРО — описан е детайлно маршрут от Зелени Преслап до връх Кабул, включително ориентири, вода и алтернативи.', '{"summary":"Най-удобно е с лична кола до Зелени Преслап; обществен транспорт и таксита не са потвърдени.","car":{"available":true,"text":"До Зелени Преслап се стига по асфалт от Сапарева баня; мястото е достъпно и за старт на прехода.","parkingNote":"Паркирането е на поляната/широкото място при изхода; точен GPS паркинг не е потвърден."},"public":{"steps":[]}}'::jsonb, '[{"name":"хижа Скакавица","elevation":null,"beds":null,"officialPhone":"0886 509 409","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Хижата е логически по маршрута/в близост, но в наличните източници тук не са потвърдени официални контакти с 2 независими извора."}]'::jsonb, '{"level":"СРЕДЕН","color":"amber","points":["Маршрутът е дълъг и много стръмен за 5.5 км.","Маркировката във втората половина не е лесна и може да изисква GPS.","Има риск от пастирски кучета и от умора при постоянния наклон."],"conclusion":"Тежък, но ясен като линия маршрут; основният риск е натоварването и ориентацията след овчарниците."}'::jsonb, '[{"date":null,"label":"Зелени Преслап → връх Кабул","type":"Преход","distance":"5.5 км","gain":"900 м","time":"3.5-5 ч","stay":null,"difficulty":"Висока"}]'::jsonb, '[{"name":"х. Скакавица","location":"Рила","rating":null,"price":null,"note":"Подходяща като база/слизане след маршрута."}]'::jsonb, '[]'::jsonb, '', '')
